//! Oracle vectors: case conversion of whole strings in all eight `MB_CASE_*` modes, plus
//! `mb_ucfirst`/`mb_lcfirst`: title-case words, the final-sigma rule at 64-code-point chunk
//! boundaries, special-casing expansions, ill-formed UTF-8, and random strings.
//!
//! `tests/vectors/case_strings.json` is generated by `tests/vectors/case_strings.gen.php` in the
//! PHP oracle (`research/php-oracle`). Regenerate from the repository root with
//!
//! ```text
//! docker run --rm -i twig-oracle:3.31.1 php < crates/twig-unicode/tests/vectors/case_strings.gen.php \
//!     > crates/twig-unicode/tests/vectors/case_strings.json
//! ```

use serde::Deserialize;
use twig_unicode::{
    CaseMode, convert_case, mb_convert_case, mb_lcfirst, mb_strtolower, mb_strtoupper, mb_ucfirst,
};

#[derive(Deserialize)]
struct Vectors {
    php_version: String,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    #[serde(rename = "in")]
    input: String,
    modes: Vec<String>,
    ucfirst: String,
    lcfirst: String,
}

fn hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn show(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).into_owned()
}

#[test]
fn strings_convert_like_php() {
    let vectors: Vectors = serde_json::from_str(include_str!("vectors/case_strings.json")).unwrap();
    assert_eq!(vectors.php_version, "8.5.13");
    assert!(vectors.cases.len() > 300);
    for case in &vectors.cases {
        let input = hex(&case.input);
        assert_eq!(case.modes.len(), 8);
        for (mode, want) in CaseMode::ALL.into_iter().zip(&case.modes) {
            let want = hex(want);
            let got = convert_case(mode, &input);
            assert_eq!(
                got,
                want,
                "{} {mode:?} {:?}: got {:?}, want {:?}",
                case.name,
                show(&input),
                show(&got),
                show(&want)
            );
            assert_eq!(mb_convert_case(&input, mode.to_php()).unwrap(), want);
        }
        assert_eq!(mb_strtoupper(&input), hex(&case.modes[0]), "{}", case.name);
        assert_eq!(mb_strtolower(&input), hex(&case.modes[1]), "{}", case.name);
        assert_eq!(
            mb_ucfirst(&input),
            hex(&case.ucfirst),
            "{} ucfirst",
            case.name
        );
        assert_eq!(
            mb_lcfirst(&input),
            hex(&case.lcfirst),
            "{} lcfirst",
            case.name
        );
    }
}
